CMAES = '''import numpy as np
from cmaes import CMA

def quadratic(x1, x2):
    return (x1 - 3) ** 2 + (10 * (x2 + 2)) ** 2

optimizer = CMA(mean=np.zeros(2), sigma=1.3)
for generation in range(50):
    solutions = []
    for _ in range(optimizer.population_size):
        x = optimizer.ask()                     # propose
        solutions.append((x, quadratic(x[0], x[1])))   # score
    optimizer.tell(solutions)                   # keep the better, adapt'''


def body(lang, A):
    L = lambda x: x[lang]
    S = []
    eng = lambda v: f"{v:,}".replace(",", "." if lang == "de" else ",")
    S.append(("intro", 0, None, L(T(
        f"""<p>Place 12 wind turbines on a square kilometre, each on one of 100 cells of 100 × 100 m. There are {LAYOUTS / 1e15:.2f} · 10<sup>15</sup> ways to choose the cells, before any spacing rule — checking a million layouts per second would take {YEARS:.0f} years. Yet any single layout can be scored in an instant: so much energy, so much loss in the wake of the neighbours. When you can rate every candidate but cannot list them all, you can let the candidates <i>evolve</i>.</p>
<p>An evolutionary algorithm keeps a <b>population</b> of candidates. It rates each by its <b>fitness</b>, lets the better ones have children — mixing their parts (<b>crossover</b>) and changing them a little at random (<b>mutation</b>) — and lets the worse ones die out (<b>selection</b>). Generation by generation, the population drifts toward good solutions. In code, it is a loop of a few lines:</p>""",
        f"""<p>Stellen Sie 12 Windkraftanlagen auf einen Quadratkilometer, jede auf eine von 100 Zellen à 100 × 100 m. Dafür gibt es {LAYOUTS / 1e15:.2f} · 10<sup>15</sup> Möglichkeiten, die Zellen zu wählen, noch ohne Abstandsregel — eine Million Layouts pro Sekunde zu prüfen, dauerte {YEARS:.0f} Jahre. Doch jedes einzelne Layout lässt sich im Nu bewerten: so viel Energie, so viel Verlust im Nachlauf der Nachbarn. Wenn man jeden Kandidaten bewerten, aber nicht alle aufzählen kann, kann man die Kandidaten <i>evolvieren</i> lassen.</p>
<p>Ein evolutionärer Algorithmus hält eine <b>Population</b> von Kandidaten. Er bewertet jeden nach seiner <b>Fitness</b>, lässt die besseren Kinder bekommen — ihre Teile mischen (<b>Crossover</b>) und ein wenig zufällig ändern (<b>Mutation</b>) — und die schlechteren aussterben (<b>Selektion</b>). Generation für Generation wandert die Population zu guten Lösungen. Im Code ist das eine Schleife aus wenigen Zeilen:</p>""".replace(f"{LAYOUTS / 1e15:.2f}", f"{LAYOUTS / 1e15:.2f}".replace(".", ","))))
        + '<pre class="mono art-pre">population = [random_candidate() for _ in range(20)]\nfor generation in range(60):\n    scored  = [(fitness(c), c) for c in population]\n    parents = select(scored)                       # the better ones, more often\n    kids    = [mutate(crossover(a, b)) for a, b in pairs(parents)]\n    population = survivors(scored, kids) + [random_candidate(), random_candidate()]\nbest = max(population, key=fitness)</pre>'
        + L(T(f"""<p>This article explains that loop, step by step, on one running example: a toy wind farm, the problem of my master’s thesis {cite('Net17')} in small. First chapter: where evolutionary algorithms sit next to the machine learning and LLMs of <a href="research-ai4se.html">part 2</a>. Second: what each step does — with figures that run real, replayable evolutions. Third: the family, two applications from my own work, and how to try it yourself.</p>""",
              f"""<p>Dieser Artikel erklärt diese Schleife Schritt für Schritt an einem durchgehenden Beispiel: einem Spielzeug-Windpark, dem Problem meiner Masterarbeit {cite('Net17')} im Kleinen. Erstes Kapitel: wo evolutionäre Algorithmen neben dem maschinellen Lernen und den LLMs aus <a href="research-ai4se.html">Teil 2</a> stehen. Zweites: was jeder Schritt tut — mit Abbildungen, in denen echte, reproduzierbare Evolutionen laufen. Drittes: die Verwandtschaft, zwei Anwendungen aus meiner eigenen Arbeit und wie man es selbst ausprobiert.</p>"""))))

    # ---------------- 01 Where EAs sit ----------------
    S.append(("place", 2, T("Where evolutionary algorithms sit", "Wo evolutionäre Algorithmen stehen"), L(T(
        "<p>Evolutionary algorithms are older than deep learning and work quite differently. To place them, ask what a method needs — and what it gives back.</p>",
        "<p>Evolutionäre Algorithmen sind älter als Deep Learning und arbeiten ganz anders. Um sie einzuordnen, fragen Sie, was ein Verfahren braucht — und was es zurückgibt.</p>"))))
    S.append(("map", 3, T("The AI map", "Die KI-Landkarte"),
        L(T(f"""<p>“AI” covers methods that have little in common. Some get a <i>formal model</i> of the problem — rules, constraints — and search it: route planners, SAT and SMT solvers. Some get <i>examples</i> and learn a model from them: regression, deep networks, LLMs. And some get <i>only a score</i>: a way to rate any candidate, without knowing why one is better. Evolutionary algorithms belong to the third group. The standard AI textbook files them under search and optimisation, next to hill climbing and simulated annealing {r('AIMA')}, not under learning.</p>""",
              f"""<p>„KI“ umfasst Verfahren, die wenig gemeinsam haben. Manche bekommen ein <i>formales Modell</i> des Problems — Regeln, Bedingungen — und durchsuchen es: Routenplaner, SAT- und SMT-Solver. Manche bekommen <i>Beispiele</i> und lernen daraus ein Modell: Regression, tiefe Netze, LLMs. Und manche bekommen <i>nur eine Bewertung</i>: einen Weg, jeden Kandidaten zu benoten, ohne zu wissen, warum einer besser ist. Evolutionäre Algorithmen gehören zur dritten Gruppe. Das Standardlehrbuch der KI ordnet sie bei Suche und Optimierung ein, neben dem Bergsteigen und Simulated Annealing {r('AIMA')}, nicht beim Lernen.</p>"""))
        + fig_map(lang)
        + L(T(f"""<p>The border to machine learning is open, though. Evolution can tune the settings of a model or even grow its network — and if you have used Optuna for hyperparameters, you may already have run an evolutionary algorithm: its CMA-ES and NSGA-II samplers are exactly that.</p>""",
              f"""<p>Die Grenze zum maschinellen Lernen ist aber offen. Evolution kann die Einstellungen eines Modells abstimmen oder sogar sein Netz wachsen lassen — und wer Optuna für Hyperparameter benutzt hat, hat vielleicht schon einen evolutionären Algorithmus laufen lassen: Seine Sampler CMA-ES und NSGA-II sind genau das.</p>"""))
        + curious(lang, T(f"""<p><b>“Genetic” is a metaphor.</b> Holland’s genetic algorithms {r('Hol75')} borrowed the words — chromosome, gene, crossover, mutation — not the biology. Eiben and Smith warn that reading evolution as optimisation is natural but “somewhat misleading” {r('ES15')}: nature has no fixed goal. This article says <i>evolutionary algorithm</i> for the whole family and <i>genetic algorithm</i> for the variant with chromosomes and crossover — the one of my thesis.</p>
<p><b>Local or global?</b> The textbook calls these methods “local search” because they keep only current candidates, not the paths to them {r('AIMA')}. A population still explores many regions at once — my thesis puts it as evolving “towards multiple optima in parallel” {cite('Net17')}.</p>""",
                          f"""<p><b>„Genetisch“ ist eine Metapher.</b> Hollands genetische Algorithmen {r('Hol75')} haben die Wörter geliehen — Chromosom, Gen, Crossover, Mutation —, nicht die Biologie. Eiben und Smith warnen, Evolution als Optimierung zu lesen, liege nahe, sei aber etwas irreführend {r('ES15')}: Die Natur hat kein festes Ziel. Dieser Artikel sagt <i>evolutionärer Algorithmus</i> für die ganze Familie und <i>genetischer Algorithmus</i> für die Variante mit Chromosomen und Crossover — die meiner Arbeit.</p>
<p><b>Lokal oder global?</b> Das Lehrbuch nennt diese Verfahren „lokale Suche“, weil sie nur aktuelle Kandidaten halten, nicht die Wege dorthin {r('AIMA')}. Eine Population erkundet trotzdem viele Gegenden zugleich — meine Arbeit sagt, sie entwickle sich parallel zu mehreren Optima hin {cite('Net17')}.</p>"""),
                  T("Genetic, local, global: three words that mislead", "Genetisch, lokal, global: drei Wörter, die irreführen"))))
    S.append(("search", 3, T("Learning from data vs searching with a score", "Aus Daten lernen vs. mit einer Bewertung suchen"),
        L(T(f"""<p>A neural network learns by <a href="research-ai4se.html#neural">gradient descent</a>: it needs examples with answers and a loss that says, for every weight, in which direction the error shrinks. An evolutionary algorithm needs neither. It needs a <i>score</i> for a candidate — which may itself come from data or from a slow simulation — and it gives back good candidates: a layout, a schedule, a test suite. Nothing is learned that would generalise to the next problem.</p>
<p>Both use randomness on purpose. In part 2, the <a href="research-ai4se.html#tokens">temperature</a> decides how often a language model picks a less likely word. In an evolutionary algorithm, randomness enters twice: in <i>selection</i>, which decides how strongly the better candidates are preferred — the <b>selection pressure</b>, which even has a temperature form (chapter 02) — and in <i>mutation</i>, which invents what no parent had.</p>""",
              f"""<p>Ein neuronales Netz lernt durch <a href="research-ai4se.html#neural">Gradientenabstieg</a>: Es braucht Beispiele mit Antworten und eine Fehlerfunktion, die für jedes Gewicht sagt, in welcher Richtung der Fehler schrumpft. Ein evolutionärer Algorithmus braucht beides nicht. Er braucht eine <i>Bewertung</i> für einen Kandidaten — die selbst aus Daten oder einer langsamen Simulation kommen kann — und er liefert gute Kandidaten: ein Layout, einen Zeitplan, eine Test-Suite. Nichts wird gelernt, was aufs nächste Problem übertragbar wäre.</p>
<p>Beide nutzen Zufall mit Absicht. In Teil 2 entscheidet die <a href="research-ai4se.html#tokens">Temperatur</a>, wie oft ein Sprachmodell ein weniger wahrscheinliches Wort wählt. In einem evolutionären Algorithmus kommt Zufall zweimal ins Spiel: bei der <i>Selektion</i>, die entscheidet, wie stark die Besseren bevorzugt werden — der <b>Selektionsdruck</b>, den es sogar in einer Temperatur-Form gibt (Kapitel 02) —, und bei der <i>Mutation</i>, die erfindet, was kein Elternteil hatte.</p>"""))
        + demo_pipes(lang)
        + L(T(f"""<p>The two worlds meet in a new way. In FunSearch {r('FunS')} and AlphaEvolve {r('AlphaE')}, building on the idea of evolution through large models {r('ELM')}, the candidates are programs: an LLM reads a few good ones and writes a variant, an automatic evaluator scores it, the best are kept and varied again. The LLM replaces the hand-written mutation — the loop and the score stay exactly as described here.</p>""",
              f"""<p>Die beiden Welten treffen sich auf neue Weise. Bei FunSearch {r('FunS')} und AlphaEvolve {r('AlphaE')}, aufbauend auf der Idee der Evolution durch große Modelle {r('ELM')}, sind die Kandidaten Programme: Ein LLM liest einige gute und schreibt eine Variante, eine automatische Bewertung benotet sie, die besten werden behalten und wieder variiert. Das LLM ersetzt die handgeschriebene Mutation — Schleife und Bewertung bleiben genau wie hier beschrieben.</p>"""))
        + curious(lang, T(f"""<p>Is there a best optimiser? No: averaged over <i>all</i> possible problems, every black-box optimiser performs the same — Wolpert and Macready’s No Free Lunch theorems {r('NFL')}. An evolutionary algorithm that knows nothing about your problem has no advantage over random search. The advantage comes from what you build in: an encoding where good parts can be combined, operators that respect the constraints, a score that rewards the right thing. Chapter 02 is about exactly these choices.</p>
<p>And one family, the evolution strategies, is closer to gradient descent than it seems: “ES can be seen as computing a finite difference derivative estimate in a randomly chosen direction” {r('Sal17')}.</p>""",
                          f"""<p>Gibt es einen besten Optimierer? Nein: Gemittelt über <i>alle</i> möglichen Probleme schneidet jeder Black-Box-Optimierer gleich ab — die No-Free-Lunch-Theoreme von Wolpert und Macready {r('NFL')}. Ein evolutionärer Algorithmus, der nichts über Ihr Problem weiß, hat keinen Vorteil gegenüber Zufallssuche. Der Vorteil kommt aus dem, was Sie einbauen: einer Codierung, in der sich gute Teile kombinieren lassen, Operatoren, die die Bedingungen respektieren, einer Bewertung, die das Richtige belohnt. Kapitel 02 handelt genau von diesen Entscheidungen.</p>
<p>Und eine Familie, die Evolutionsstrategien, steht dem Gradientenabstieg näher, als es scheint: Sie lassen sich als Schätzung einer Ableitung durch endliche Differenzen in einer zufälligen Richtung lesen {r('Sal17')}.</p>"""),
                  T("No free lunch", "Kein kostenloses Mittagessen"))))
    S.append(("sbse", 3, T("Evolution in software engineering", "Evolution in der Softwaretechnik"),
        L(T(f"""<p>In 2001, Harman and Jones proposed to treat software-engineering problems the same way: find a representation for a candidate and a fitness to score it, and let a search do the rest — <i>search-based software engineering</i> {r('HJ01')}. Two examples show how far this goes.</p>
<ul class="pts"><li><b>Test generation.</b> EvoSuite evolves whole test suites for Java classes. A suite is scored by what it misses: uncovered methods plus the <i>branch distance</i> — for <code>if (x &gt;= 10)</code> run with x = 5, the distance to the missing branch is 10 − 5 + k, a small k &gt; 0 ensuring that a branch that was only just missed still counts as uncovered — so the search gets a slope toward the branch instead of a flat “not covered” {r('FA13')}.</li>
<li><b>Program repair.</b> GenProg evolves patches until the failing test passes; it fixed 55 of 105 bugs for about eight dollars each {r('LeG12')}. A later analysis found that most of these patches were not correct — many simply deleted the faulty functionality, and a system that only deletes produced at least as many correct patches {r('Qi15')}. The tests were the fitness, and the tests did not forbid deleting.</li></ul>
<p>That second story is the most important lesson of this article in one sentence: <b>evolution optimises exactly what you measure</b>. The same search also speeds up existing programs — genetic improvement made a 50,000-line bioinformatics tool 70 times faster on average on its benchmark {r('LH15')} — and tests apps at scale: Sapienz found 558 unknown crashes in the top 1,000 Android apps {r('Mao16')}.</p>""",
              f"""<p>2001 schlugen Harman und Jones vor, Probleme der Softwaretechnik genauso zu behandeln: eine Darstellung für einen Kandidaten und eine Fitness zu seiner Bewertung finden und den Rest einer Suche überlassen — <i>suchbasierte Softwaretechnik</i> {r('HJ01')}. Zwei Beispiele zeigen, wie weit das trägt.</p>
<ul class="pts"><li><b>Testgenerierung.</b> EvoSuite evolviert ganze Test-Suiten für Java-Klassen. Eine Suite wird danach bewertet, was ihr fehlt: nicht erreichte Methoden plus die <i>Zweig-Distanz</i> — für <code>if (x &gt;= 10)</code>, ausgeführt mit x = 5, ist die Distanz zum fehlenden Zweig 10 − 5 + k; ein kleines k &gt; 0 sorgt dafür, dass ein knapp verfehlter Zweig noch als nicht erreicht zählt —, so bekommt die Suche ein Gefälle zum Zweig statt eines flachen „nicht erreicht“ {r('FA13')}.</li>
<li><b>Programmreparatur.</b> GenProg evolviert Patches, bis der fehlschlagende Test besteht; es reparierte 55 von 105 Fehlern für rund acht Dollar pro Stück {r('LeG12')}. Eine spätere Analyse zeigte, dass die meisten dieser Patches nicht korrekt waren — viele löschten einfach die fehlerhafte Funktion, und ein System, das nur löscht, erzeugte mindestens so viele korrekte Patches {r('Qi15')}. Die Tests waren die Fitness, und die Tests verboten das Löschen nicht.</li></ul>
<p>Die zweite Geschichte ist die wichtigste Lehre dieses Artikels in einem Satz: <b>Evolution optimiert genau das, was Sie messen</b>. Dieselbe Suche beschleunigt auch bestehende Programme — Genetic Improvement machte ein Bioinformatik-Werkzeug mit 50.000 Zeilen auf seinem Benchmark im Mittel 70-mal schneller {r('LH15')} — und testet Apps im großen Maßstab: Sapienz fand 558 unbekannte Abstürze in den 1.000 meistgenutzten Android-Apps {r('Mao16')}.</p>"""))))

    # ---------------- 02 How an EA works ----------------
    S.append(("how", 2, T("How an evolutionary algorithm works", "Wie ein evolutionärer Algorithmus arbeitet"), L(T(
        f"""<p>The running example: a site of 1 × 1 km, 12 turbines, at least 240 m apart (three rotor diameters). The toy score, taken from the test objectives of my thesis, says that the wind is better toward the north-east: a turbine in the south-west corner scores 0, one in the north-east corner 1; a layout’s fitness is the mean over its turbines. Wakes are off for now — they come back in the fitness section. A run starts with 20 random layouts and evolves them for 60 generations.</p>""",
        f"""<p>Das durchgehende Beispiel: ein Gelände von 1 × 1 km, 12 Turbinen, mindestens 240 m voneinander entfernt (drei Rotordurchmesser). Die Spielzeug-Bewertung, aus den Testzielen meiner Arbeit, sagt, dass der Wind nach Nordosten besser wird: Eine Turbine in der Südwestecke bekommt 0, eine in der Nordostecke 1; die Fitness eines Layouts ist der Mittelwert über seine Turbinen. Nachläufe sind vorerst aus — sie kommen im Abschnitt zur Fitness zurück. Ein Lauf beginnt mit 20 zufälligen Layouts und evolviert sie über 60 Generationen.</p>"""))))
    S.append(("loop", 3, T("The loop", "Die Schleife"),
        L(T(f"""<p>One pass through the loop is a <b>generation</b>; the candidates of a generation are the <b>population</b>; one candidate is a <b>chromosome</b>, its parts are <b>genes</b>. Each generation, the algorithm checks whether to stop, selects parents, pairs them up, recombines each pair into a child, mutates some children, scores them, drops the worst of parents and children, and adds a few random newcomers. Step through one real generation:</p>""",
              f"""<p>Ein Durchlauf durch die Schleife ist eine <b>Generation</b>; die Kandidaten einer Generation sind die <b>Population</b>; ein Kandidat ist ein <b>Chromosom</b>, seine Teile sind <b>Gene</b>. In jeder Generation prüft der Algorithmus, ob er aufhört, wählt Eltern, bildet Paare, kreuzt jedes Paar zu einem Kind, mutiert einige Kinder, bewertet sie, streicht die schlechtesten aus Eltern und Kindern und fügt ein paar zufällige Neulinge hinzu. Gehen Sie eine echte Generation durch:</p>"""))
        + demo_loop(lang)
        + L(T(f"""<p>Every library draws this loop a little differently, but the shape is always the same, and it can be folded into three verbs: <i>ask</i> for new candidates (select, pair, recombine, mutate), <i>evaluate</i> them, <i>tell</i> the algorithm the scores (it decides who survives). That is how libraries such as CMA-ES present it. In <a href="projects-geneial.html">geneial</a>, the library of my thesis, each step is an exchangeable building block with its own builder. Two words will come up in every section:</p>""",
              f"""<p>Jede Bibliothek zeichnet diese Schleife etwas anders, aber die Form ist immer dieselbe, und sie lässt sich in drei Verben falten: neue Kandidaten <i>erfragen</i> (wählen, paaren, kreuzen, mutieren), sie <i>bewerten</i>, dem Algorithmus die Bewertungen <i>mitteilen</i> (er entscheidet, wer überlebt). So stellen es Bibliotheken wie CMA-ES dar. In <a href="projects-geneial.html">geneial</a>, der Bibliothek meiner Arbeit, ist jeder Schritt ein austauschbarer Baustein mit eigenem Builder. Zwei Begriffe kommen in jedem Abschnitt vor:</p>"""))
        + definition(T("Selection pressure", "Selektionsdruck"), T("How strongly the better candidates are preferred. Too little, and the search drifts; too much, and the population collapses onto the first good idea.",
                                                               "Wie stark die besseren Kandidaten bevorzugt werden. Zu wenig, und die Suche treibt ziellos; zu viel, und die Population fällt auf die erste gute Idee zusammen."), lang)
        + definition(T("Exploration vs exploitation", "Erkunden vs. Ausnutzen"), T(f"Searching new regions vs refining near what is known to be good. Every knob of the loop moves the balance between the two {r('ES15')}.",
                                                                                  f"Neue Gegenden durchsuchen vs. in der Nähe des bekannt Guten verfeinern. Jeder Regler der Schleife verschiebt das Gleichgewicht zwischen beidem {r('ES15')}."), lang)
        + curious(lang, T(f"""<p>Not every algorithm replaces its whole population each generation. Here, as in geneial, 6 children compete with 20 parents and only the 8 worst of all 26 go: generations <i>overlap</i>, and because the best always survive, the algorithm is elitist by construction. Evolution strategies name the two choices: (μ + λ) selects the survivors from parents and children together, (μ, λ) only from the children — the parents are forgotten, which helps to escape from a good-looking spot {r('BS02')}.</p>""",
                          f"""<p>Nicht jeder Algorithmus ersetzt in jeder Generation seine ganze Population. Hier, wie in geneial, konkurrieren 6 Kinder mit 20 Eltern, und nur die 8 schlechtesten aller 26 gehen: Generationen <i>überlappen</i>, und weil die Besten immer überleben, ist der Algorithmus von Haus aus elitär. Evolutionsstrategien benennen die beiden Möglichkeiten: (μ + λ) wählt die Überlebenden aus Eltern und Kindern zusammen, (μ, λ) nur aus den Kindern — die Eltern werden vergessen, was hilft, einer gut aussehenden Stelle zu entkommen {r('BS02')}.</p>"""),
                  T("Overlapping generations, plus and comma", "Überlappende Generationen, Plus und Komma"))))
    S.append(("encoding", 3, T("Encoding: what a candidate is", "Codierung: was ein Kandidat ist"),
        L(T(f"""<p>The <b>genotype</b> is what the algorithm manipulates; the <b>phenotype</b> is what it means. For the wind farm, the obvious genotype is a list of 12 positions. They can be free floating-point coordinates — or coordinates snapped to the centres of a grid of ρ × ρ cells. My thesis compared exactly these two <i>grid genes</i> and <i>float genes</i> {cite('Net17')}. The grid is a design decision with consequences you may not expect:</p>""",
              f"""<p>Der <b>Genotyp</b> ist das, was der Algorithmus bearbeitet; der <b>Phänotyp</b> ist das, was er bedeutet. Für den Windpark ist der naheliegende Genotyp eine Liste von 12 Positionen. Das können freie Gleitkomma-Koordinaten sein — oder Koordinaten, die auf die Mittelpunkte eines Rasters aus ρ × ρ Zellen gerundet werden. Meine Arbeit hat genau diese beiden verglichen, <i>Rastergene</i> und <i>Gleitkomma-Gene</i> {cite('Net17')}. Das Raster ist eine Entwurfsentscheidung mit Folgen, die man nicht erwartet:</p>"""))
        + demo_encoding(lang)
        + L(T(f"""<p>The lesson of the thesis, in its own words: “There is no benefit in using a resolution that exceeds the one of the objective function” {cite('Net17')} — resolve no finer than your score can tell apart. And the encoding decides which operators make sense. A list of numbers in a fixed order — a schedule, second by second — can be cut and spliced. A set of positions has no order: which turbine is “gene 3”? It needs its own crossover (below). The first population comes from a <b>chromosome factory</b>: it draws random positions one by one and reverts any that break the spacing, so that every candidate is valid from the start.</p>""",
              f"""<p>Die Lehre der Arbeit, in ihren eigenen Worten: „There is no benefit in using a resolution that exceeds the one of the objective function“ {cite('Net17')} — lösen Sie nicht feiner auf, als Ihre Bewertung unterscheiden kann. Und die Codierung entscheidet, welche Operatoren sinnvoll sind. Eine Liste von Zahlen in fester Reihenfolge — ein Zeitplan, Sekunde für Sekunde — lässt sich schneiden und neu zusammensetzen. Eine Menge von Positionen hat keine Reihenfolge: Welche Turbine ist „Gen 3“? Sie braucht einen eigenen Crossover (unten). Die erste Population liefert eine <b>Chromosomen-Fabrik</b>: Sie zieht zufällige Positionen nacheinander und nimmt jede zurück, die den Abstand verletzt, damit jeder Kandidat von Anfang an gültig ist.</p>"""))
        + fig_chromosomes(lang)
        + curious(lang, T(f"""<p>The textbook encoding for wind farms is one bit per cell: 1 = a turbine stands here {r('Gra05')}. It is intuitive and fine for coarse grids. But the thesis did the arithmetic for a fine one: at ρ = 10,000, a single chromosome has 10<sup>8</sup> bits, and a population of 1000 would need hundreds of gigabytes {cite('Net17')}. A list of coordinates stays the same size however fine the grid — 12 pairs of numbers. And a fun fact on precision: two neighbouring 64-bit floating-point numbers near 1000 m are about 10<sup>−13</sup> m apart — far below the size of an atom. No wind model resolves that.</p>""",
                          f"""<p>Die Lehrbuch-Codierung für Windparks ist ein Bit je Zelle: 1 = hier steht eine Turbine {r('Gra05')}. Sie ist anschaulich und für grobe Raster gut. Für ein feines Raster hat die Arbeit aber nachgerechnet: Bei ρ = 10.000 hat ein einziges Chromosom 10<sup>8</sup> Bits, und eine Population von 1000 bräuchte Hunderte Gigabyte {cite('Net17')}. Eine Liste von Koordinaten bleibt gleich groß, wie fein das Raster auch ist — 12 Zahlenpaare. Und eine Kuriosität zur Genauigkeit: Zwei benachbarte 64-Bit-Gleitkommazahlen nahe 1000 m liegen etwa 10<sup>−13</sup> m auseinander — weit unter der Größe eines Atoms. Kein Windmodell löst das auf.</p>"""),
                  T("How big is the search space, honestly?", "Wie groß ist der Suchraum wirklich?"))))
    S.append(("fitness", 3, T("Fitness: the score is the specification", "Fitness: Die Bewertung ist die Spezifikation"),
        L(T(f"""<p>The fitness function is the only thing the algorithm knows about your problem. In the real wind farm it is a chain of models: wind statistics, the wake behind each turbine, the power curve, and finally money — energy per year, cost per megawatt hour, net present value or rate of return {cite('Net17')}. Such a simulation can take “several minutes up to days” per candidate {cite('Net17')}, which is why the thesis also has toy scores like ours. Here are the wakes switched on:</p>""",
              f"""<p>Die Fitnessfunktion ist das Einzige, was der Algorithmus über Ihr Problem weiß. Im echten Windpark ist sie eine Kette von Modellen: Windstatistik, der Nachlauf hinter jeder Turbine, die Leistungskurve und schließlich Geld — Energie pro Jahr, Kosten je Megawattstunde, Kapitalwert oder Rendite {cite('Net17')}. So eine Simulation kann je Kandidat Minuten bis Tage dauern {cite('Net17')}, deshalb hat die Arbeit auch Spielzeug-Bewertungen wie unsere. Hier sind die Nachläufe eingeschaltet:</p>"""))
        + demo_wake(lang)
        + L(T(f"""<p>Three practical points. <b>Budget:</b> the cost of a run is the number of evaluations, roughly population × generations — our toy run needs 20 + 60 × 8 = 500 (six children and two newcomers per generation), at one minute each more than eight hours; evaluate in parallel and cache scores. <b>Constraints:</b> invalid candidates can be repaired (the factory, the crossover below), penalised in the score, or made impossible by the encoding (the hybrid car in chapter 03). <b>Direction:</b> this article maximises; many libraries minimise — negate the score.</p>
<p>And the most important point, again: the score <i>is</i> the specification. The GenProg patches passed the tests by deleting features; the hybrid-car controller in chapter 03 used more fuel when told to care only about fuel.</p>""",
              f"""<p>Drei praktische Punkte. <b>Budget:</b> Die Kosten eines Laufs sind die Zahl der Bewertungen, ungefähr Population × Generationen — unser Spielzeuglauf braucht 20 + 60 × 8 = 500 (sechs Kinder und zwei Neulinge je Generation), bei einer Minute je Bewertung mehr als acht Stunden; bewerten Sie parallel und speichern Sie Ergebnisse zwischen. <b>Nebenbedingungen:</b> Ungültige Kandidaten lassen sich reparieren (die Fabrik, der Crossover unten), in der Bewertung bestrafen oder durch die Codierung unmöglich machen (das Hybridauto in Kapitel 03). <b>Richtung:</b> Dieser Artikel maximiert; viele Bibliotheken minimieren — drehen Sie das Vorzeichen um.</p>
<p>Und der wichtigste Punkt, noch einmal: Die Bewertung <i>ist</i> die Spezifikation. Die GenProg-Patches bestanden die Tests, indem sie Funktionen löschten; die Hybridauto-Steuerung in Kapitel 03 verbrauchte mehr Kraftstoff, als man ihr sagte, nur auf Kraftstoff zu achten.</p>"""))
        + curious(lang, T(f"""<p>A good specification can make evolution beat engineers. For NASA’s Space Technology 5 mission, Lohn and colleagues evolved the shape of a small wire antenna. To survive manufacturing tolerances, every design was simulated several times with small random perturbations of its angles and wire radii — and its fitness was the <i>worst</i> of these runs {r('ST5')}. The result looked like a bent paperclip, met the requirements, and flew on the mission in 2006 — the first evolved hardware in space {r('HLL11')}.</p>""",
                          f"""<p>Eine gute Spezifikation kann Evolution besser machen als Ingenieure. Für die NASA-Mission Space Technology 5 haben Lohn und Kollegen die Form einer kleinen Drahtantenne evolviert. Damit sie Fertigungstoleranzen übersteht, wurde jeder Entwurf mehrmals mit kleinen zufälligen Störungen seiner Winkel und Drahtradien simuliert — und seine Fitness war das <i>schlechteste</i> dieser Ergebnisse {r('ST5')}. Das Ergebnis sah aus wie eine verbogene Büroklammer, erfüllte die Anforderungen und flog 2006 mit — die erste evolvierte Hardware im All {r('HLL11')}.</p>"""),
                  T("When the specification is right: the NASA antenna", "Wenn die Spezifikation stimmt: die NASA-Antenne"))))
    S.append(("selection", 3, T("Selection: who gets to have children", "Selektion: wer Kinder bekommen darf"),
        L(T(f"""<p>Selection turns fitness into chances. The classic <b>roulette wheel</b> gives each candidate a slice proportional to its fitness {r('Gol89')}, as in my thesis {cite('Net17')}. It has a weakness you can try below: it depends on the absolute numbers. A <b>tournament</b> draws k candidates at random and takes the best — it only compares, and k is a single dial for the pressure {r('GD91')}. A softmax with a <b>temperature</b> sits in between, exactly like the token choice of a language model.</p>""",
              f"""<p>Die Selektion macht aus Fitness Chancen. Das klassische <b>Glücksrad</b> gibt jedem Kandidaten ein Stück proportional zu seiner Fitness {r('Gol89')}, wie in meiner Arbeit {cite('Net17')}. Es hat eine Schwäche, die Sie unten ausprobieren können: Es hängt von den absoluten Zahlen ab. Ein <b>Turnier</b> zieht k Kandidaten zufällig und nimmt den besten — es vergleicht nur, und k ist ein einziger Regler für den Druck {r('GD91')}. Ein Softmax mit <b>Temperatur</b> liegt dazwischen, genau wie die Token-Wahl eines Sprachmodells.</p>"""))
        + demo_selection(lang)
        + L(T(f"""<p><b>Elitism</b> copies the best candidates unchanged into the next generation, so the best score can never get worse. But selection should not only pick the best: the thesis recommends to “select a few ‘bad’ chromosomes” as well, because the diversity “is needed to break free from local maxima” {cite('Net17')}.</p>""",
              f"""<p><b>Elitismus</b> übernimmt die besten Kandidaten unverändert in die nächste Generation, sodass die beste Bewertung nie schlechter werden kann. Selektion sollte aber nicht nur die Besten nehmen: Die Arbeit empfiehlt, auch ein paar „schlechte“ Chromosomen zu wählen, weil die Vielfalt nötig ist, um lokalen Maxima zu entkommen {cite('Net17')}.</p>"""))
        + curious(lang, T(f"""<p>How fast does selection alone — without crossover and mutation — fill a population with copies of the best? Goldberg and Deb called this the <i>takeover time</i> and compared the common schemes: proportional selection is slow when the scores are close together, tournament and ranking selection take over in a number of generations that grows only with the logarithm of the population size {r('GD91')}. Fast takeover is good for exploitation and bad for exploration — the same balance again.</p>""",
                          f"""<p>Wie schnell füllt Selektion allein — ohne Crossover und Mutation — eine Population mit Kopien des Besten? Goldberg und Deb nannten das <i>Takeover-Zeit</i> und verglichen die üblichen Verfahren: Proportionale Selektion ist langsam, wenn die Bewertungen nah beieinander liegen; Turnier- und Rangselektion übernehmen in einer Zahl von Generationen, die nur mit dem Logarithmus der Populationsgröße wächst {r('GD91')}. Schnelle Übernahme ist gut fürs Ausnutzen und schlecht fürs Erkunden — wieder dasselbe Gleichgewicht.</p>"""),
                  T("Takeover time", "Takeover-Zeit"))))
    S.append(("crossover", 3, T("Pairing and crossover", "Paarung und Crossover"),
        L(T(f"""<p>The selected parents are paired at random — in my thesis this is the <i>coupling</i> step; one parent can be in several pairs. <b>Crossover</b> then builds a child from both: the hope is that good parts of two parents combine into something better than either. How depends entirely on the encoding.</p>""",
              f"""<p>Die gewählten Eltern werden zufällig zu Paaren — in meiner Arbeit ist das der Schritt <i>Kopplung</i>; ein Elternteil kann in mehreren Paaren stehen. Der <b>Crossover</b> baut dann aus beiden ein Kind: in der Hoffnung, dass sich gute Teile zweier Eltern zu etwas Besserem verbinden als jedes allein. Wie, hängt ganz von der Codierung ab.</p>"""))
        + demo_crossover(lang)
        + L(T(f"""<p>One-Step crossover does not create a single new position; it only recombines. Problem-aware operators like this one beat generic ones in my thesis {cite('Net17')} — but only because the simulation reports a score for every turbine. If your evaluator returns one number per candidate, there is nothing to rank by. The general rule: <i>if your evaluator can give partial scores, use them.</i></p>""",
              f"""<p>Der One-Step-Crossover erzeugt keine einzige neue Position; er kombiniert nur neu. Problembewusste Operatoren wie dieser schlugen in meiner Arbeit die generischen {cite('Net17')} — aber nur, weil die Simulation für jede Turbine einen Wert liefert. Gibt Ihre Bewertung nur eine Zahl je Kandidat zurück, gibt es nichts, wonach man sortieren könnte. Die allgemeine Regel: <i>Wenn Ihre Bewertung Teilwerte liefern kann, nutzen Sie sie.</i></p>"""))
        + curious(lang, T(f"""<p>Why should crossover work at all? Holland’s <i>schema theorem</i> {r('Hol75')} gives a lower bound for how often short, above-average patterns of genes — schemata — are expected to appear in the next generation. That much is a theorem, under its assumptions. The popular follow-up, the <i>building-block hypothesis</i> — that GAs work by assembling such good blocks into ever better solutions — is contested {r('ES15')}. One thing is certain and easy to check: crossover does not change how often a value occurs at a position across the population; it only reshuffles the combinations. New values come only from mutation and newcomers.</p>""",
                          f"""<p>Warum sollte Crossover überhaupt funktionieren? Hollands <i>Schema-Theorem</i> {r('Hol75')} gibt eine untere Schranke dafür, wie oft kurze, überdurchschnittliche Muster von Genen — Schemata — in der nächsten Generation zu erwarten sind. So weit ist es ein Theorem, unter seinen Annahmen. Die beliebte Fortsetzung, die <i>Baustein-Hypothese</i> — dass GAs funktionieren, indem sie solche guten Blöcke zu immer besseren Lösungen zusammensetzen —, ist umstritten {r('ES15')}. Eines ist sicher und leicht nachzuprüfen: Crossover ändert nicht, wie oft ein Wert an einer Position in der Population vorkommt; er mischt nur die Kombinationen neu. Neue Werte kommen nur aus Mutation und Neulingen.</p>"""),
                  T("Building blocks, carefully", "Bausteine, mit Vorsicht"))))
    S.append(("mutation", 3, T("Mutation: three knobs", "Mutation: drei Regler"),
        L(T(f"""<p>Mutation changes a child at random, a little. It is the only step that invents something no parent had — and it can also spoil a good child, which is why my thesis does not mutate every child but <i>chooses</i> some first {cite('Net17')}. “Mutation rate” sounds like one setting; in fact there are three:</p>""",
              f"""<p>Mutation ändert ein Kind zufällig, ein wenig. Sie ist der einzige Schritt, der etwas erfindet, das kein Elternteil hatte — und sie kann auch ein gutes Kind verderben, deshalb mutiert meine Arbeit nicht jedes Kind, sondern <i>wählt</i> zuerst einige aus {cite('Net17')}. „Mutationsrate“ klingt nach einer Einstellung; tatsächlich sind es drei:</p>"""))
        + demo_mutation(lang)
        + L(T(f"""<p>What the thesis found: mutation lowers the average fitness of a population — and without it, runs freeze at different levels, depending on luck. For float genes, big steps helped early and small ones late, but “the extend of the influence of the mutation rate is small” {cite('Net17')}. Mutation is also the slot that the LLMs from chapter 01 fill: in FunSearch and AlphaEvolve, the “mutation” is a language model rewriting a program.</p>""",
              f"""<p>Was die Arbeit fand: Mutation senkt die mittlere Fitness einer Population — und ohne sie frieren Läufe auf verschiedenen Niveaus ein, je nach Glück. Bei Gleitkomma-Genen halfen große Schritte früh und kleine spät, aber der Einfluss der Schrittweite war klein {cite('Net17')}. Mutation ist auch der Platz, den die LLMs aus Kapitel 01 füllen: Bei FunSearch und AlphaEvolve ist die „Mutation“ ein Sprachmodell, das ein Programm umschreibt.</p>"""))
        + curious(lang, T(f"""<p>Choosing the step size by hand is tedious, so evolution strategies let it adapt. Rechenberg’s <i>1/5 success rule</i>: if more than a fifth of the mutations improve, take bigger steps; if fewer, smaller ones {r('BS02')}. <i>Self-adaptation</i> puts the step size into the genome, so that it evolves along. CMA-ES goes furthest: it learns a whole covariance matrix — which directions are promising and how they correlate — from the path the search has taken {r('Han16')}.</p>""",
                          f"""<p>Die Schrittweite von Hand zu wählen ist mühsam, deshalb lassen Evolutionsstrategien sie sich anpassen. Rechenbergs <i>1/5-Erfolgsregel</i>: Verbessert mehr als ein Fünftel der Mutationen, größere Schritte nehmen; weniger, kleinere {r('BS02')}. <i>Selbstanpassung</i> legt die Schrittweite ins Genom, sodass sie mit-evolviert. CMA-ES geht am weitesten: Es lernt eine ganze Kovarianzmatrix — welche Richtungen vielversprechend sind und wie sie zusammenhängen — aus dem Weg, den die Suche genommen hat {r('Han16')}.</p>"""),
                  T("Step sizes that tune themselves", "Schrittweiten, die sich selbst einstellen"))))
    S.append(("replacement", 3, T("Survivors, newcomers and diversity", "Überlebende, Neulinge und Vielfalt"),
        L(T(f"""<p>After the children are scored, the worst of parents and children are dropped, and a few random <b>newcomers</b> from the factory are added — <i>after</i> the culling, “to maintain a sufficient variety” {cite('Net17')}: they are almost always below average and would not survive a fair comparison. Why bother? Because “an evolutionary algorithm converges when the diversity of its population breaks down and most of its individuals become similar” {cite('Net17')} — and if that happens too early, it has converged on the wrong hill. Watch it happen on a landscape with two hills, where the whole search space fits on screen:</p>""",
              f"""<p>Nachdem die Kinder bewertet sind, fallen die schlechtesten aus Eltern und Kindern weg, und ein paar zufällige <b>Neulinge</b> aus der Fabrik kommen dazu — <i>nach</i> dem Aussieben, um genug Vielfalt zu erhalten {cite('Net17')}: Sie liegen fast immer unter dem Durchschnitt und würden einen fairen Vergleich nicht überleben. Wozu also? Weil ein evolutionärer Algorithmus konvergiert, wenn die Vielfalt seiner Population zusammenbricht und die meisten Individuen einander ähneln {cite('Net17')} — und passiert das zu früh, ist er auf dem falschen Hügel konvergiert. Sehen Sie zu, auf einer Landschaft mit zwei Hügeln, bei der der ganze Suchraum auf den Bildschirm passt:</p>"""))
        + demo_converge(lang)
        + L(T(f"""<p>Three ways to read such charts — they are worth logging in any real run. Diversity flat early: too much pressure. The mean no better than random: too many newcomers, the run has become random search. And always compare against random search with the same number of evaluations: here it found the right hill in all 10 runs — but reached its top in only {R_TOP} of them, the balanced setting in {B_TOP}. A good evolutionary algorithm explores <i>and</i> refines.</p>""",
              f"""<p>Drei Arten, solche Diagramme zu lesen — es lohnt sich, sie in jedem echten Lauf mitzuschreiben. Vielfalt früh flach: zu viel Druck. Der Mittelwert nicht besser als Zufall: zu viele Neulinge, der Lauf ist zur Zufallssuche geworden. Und vergleichen Sie immer mit Zufallssuche bei gleich vielen Bewertungen: Hier fand sie in allen 10 Läufen den richtigen Hügel — erreichte seine Spitze aber nur in {R_TOP} davon, die ausgewogene Einstellung in {B_TOP}. Ein guter evolutionärer Algorithmus erkundet <i>und</i> verfeinert.</p>"""))
        + curious(lang, T(f"""<p>Random newcomers are only one way to keep diversity. <i>Fitness sharing</i> divides the score of candidates that crowd the same spot, so that a crowded hill becomes less attractive; <i>crowding</i> lets a child replace the parent it resembles most, so that niches survive {r('ES15')}. <i>Novelty search</i> goes all the way and rewards being different instead of being good — and still finds good solutions on deceptive problems {r('LS11')}. Its descendants, such as MAP-Elites, keep an archive of the best candidate for each kind of behaviour (chapter 03).</p>""",
                          f"""<p>Zufällige Neulinge sind nur ein Weg, Vielfalt zu erhalten. <i>Fitness Sharing</i> teilt die Bewertung von Kandidaten, die sich an derselben Stelle drängen, sodass ein überfüllter Hügel weniger attraktiv wird; <i>Crowding</i> lässt ein Kind das Elternteil ersetzen, dem es am meisten ähnelt, sodass Nischen überleben {r('ES15')}. <i>Novelty Search</i> geht den ganzen Weg und belohnt Anderssein statt Gutsein — und findet bei täuschenden Problemen trotzdem gute Lösungen {r('LS11')}. Ihre Nachfahren wie MAP-Elites halten ein Archiv mit dem besten Kandidaten für jede Art von Verhalten (Kapitel 03).</p>"""),
                  T("Keeping diversity on purpose", "Vielfalt mit Absicht erhalten"))))
    S.append(("stopping", 3, T("When to stop", "Wann aufhören"),
        L(T(f"""<p>In most real problems you do not know the best possible score — the optimum is “simply unknown” {cite('Net17')}. So runs stop after a budget: a number of generations, of evaluations, or of seconds; or when the best has not improved for a while; or when a target is reached. Criteria can be combined. The hybrid car in chapter 03 stops after exactly 100 generations, because the controller must answer in fixed time {cite('NWN+15')}. Evolutionary algorithms are <i>anytime</i> algorithms: you can stop them whenever you like and take the best so far — and most of the gain usually comes early, as the charts above show.</p>""",
              f"""<p>Bei den meisten echten Problemen kennt man die bestmögliche Bewertung nicht — das Optimum ist schlicht unbekannt {cite('Net17')}. Läufe stoppen deshalb nach einem Budget: einer Zahl von Generationen, Bewertungen oder Sekunden; oder wenn sich das Beste eine Weile nicht verbessert hat; oder wenn ein Ziel erreicht ist. Kriterien lassen sich kombinieren. Das Hybridauto in Kapitel 03 stoppt nach genau 100 Generationen, weil die Steuerung in fester Zeit antworten muss {cite('NWN+15')}. Evolutionäre Algorithmen sind <i>Anytime</i>-Algorithmen: Man kann sie jederzeit anhalten und das bisher Beste nehmen — und der meiste Gewinn kommt meist früh, wie die Diagramme oben zeigen.</p>"""))
        + L(T(f"""<div class="tryit"><span class="k mono">SENSIBLE FIRST SETTINGS</span><p>The setup my thesis recommends for grid genes {cite('Net17')} — a starting point, not a law: <b>100</b> candidates; <b>half</b> of them selected as parents; an elite of <b>10</b>; <b>10 %</b> of the children mutated, moving 1 to 5 genes; <b>10</b> random newcomers per generation. Then: run at least ten seeds, log best, mean and diversity, and beat random search with the same budget.</p></div>""",
              f"""<div class="tryit"><span class="k mono">VERNÜNFTIGE ERSTE EINSTELLUNGEN</span><p>Die Einstellung, die meine Arbeit für Rastergene empfiehlt {cite('Net17')} — ein Startpunkt, kein Gesetz: <b>100</b> Kandidaten; die <b>Hälfte</b> davon als Eltern gewählt; eine Elite von <b>10</b>; <b>10 %</b> der Kinder mutiert, mit 1 bis 5 verschobenen Genen; <b>10</b> zufällige Neulinge je Generation. Dann: mindestens zehn Seeds laufen lassen, Bestes, Mittel und Vielfalt mitschreiben und Zufallssuche mit gleichem Budget schlagen.</p></div>"""))
        + cheat_sheet(lang)
        + curious(lang, T(f"""<p>Who tunes the tuner? Every setting above is itself a parameter of the search, and choosing them is an optimisation problem of its own — my thesis notes that GA configurations are often tuned by GAs {cite('Net17')}. The field distinguishes <i>parameter tuning</i>, fixing the settings before a run, from <i>parameter control</i>, changing them during the run, as the self-adapting step sizes do {r('ES15')}. One idea from the thesis’s future work: start with a coarse grid and refine it while the run converges.</p>""",
                          f"""<p>Wer stellt den Einsteller ein? Jede Einstellung oben ist selbst ein Parameter der Suche, und sie zu wählen ist ein eigenes Optimierungsproblem — meine Arbeit merkt an, dass GA-Konfigurationen oft mit GAs eingestellt werden {cite('Net17')}. Das Fach unterscheidet <i>Parameter-Tuning</i>, die Einstellungen vor einem Lauf festlegen, von <i>Parameter-Kontrolle</i>, sie während des Laufs ändern, wie es die selbstanpassenden Schrittweiten tun {r('ES15')}. Eine Idee aus dem Ausblick der Arbeit: mit einem groben Raster beginnen und es verfeinern, während der Lauf konvergiert.</p>"""),
                  T("Tuning the tuner", "Den Einsteller einstellen"))))

    # ---------------- 03 In practice ----------------
    S.append(("practice", 2, T("Evolutionary algorithms in practice", "Evolutionäre Algorithmen in der Praxis"), L(T(
        "<p>The family beyond the genetic algorithm, two problems from my own work, and how to start.</p>",
        "<p>Die Familie jenseits des genetischen Algorithmus, zwei Probleme aus meiner eigenen Arbeit und wie man anfängt.</p>"))))
    S.append(("family", 3, T("The family", "Die Familie"),
        L(T(f"""<p>“Evolutionary algorithm” is a family name. Its members differ mainly in two choices: what a candidate is — which decides how it can be varied — and what you want back — which decides what survives.</p>""",
              f"""<p>„Evolutionärer Algorithmus“ ist ein Familienname. Die Mitglieder unterscheiden sich vor allem in zwei Entscheidungen: was ein Kandidat ist — das entscheidet, wie er variiert werden kann — und was man zurückhaben will — das entscheidet, was überlebt.</p>"""))
        + fig_family(lang)
        + L(T(f"""<ul class="pts"><li><b>Genetic algorithms</b> (GA): strings of genes, crossover as the main operator {r('Hol75')} {r('Gol89')} — the dialect of this article.</li>
<li><b>Evolution strategies</b> (ES) and <b>CMA-ES</b>: real-valued vectors, mutation with adapting step sizes {r('BS02')} {r('Han16')}. The default for continuous parameters.</li>
<li><b>Differential evolution</b> (DE): mutates by adding the difference of two other candidates, then crosses with the parent and keeps the better of the two {r('SP97')}.</li>
<li><b>Genetic programming</b> (GP): candidates are programs — the basis of GenProg and genetic improvement.</li>
<li><b>NSGA-II</b>: several objectives at once; returns a Pareto front of trade-offs instead of one best {r('Deb02')}. In model-driven engineering, PerOpteryx uses it to optimise software architecture models for performance, reliability and cost {r('PerOp')} — see <a href="research-mde.html">part 1</a> for models.</li>
<li><b>MAP-Elites</b> and novelty search: keep the best candidate for every kind of behaviour {r('MC15')} — AlphaEvolve’s program database is inspired by it {r('AlphaE')}.</li>
<li><b>NEAT</b> and neuroevolution: evolve neural networks, topology included {r('SM02')}.</li></ul>""",
              f"""<ul class="pts"><li><b>Genetische Algorithmen</b> (GA): Ketten von Genen, Crossover als Hauptoperator {r('Hol75')} {r('Gol89')} — der Dialekt dieses Artikels.</li>
<li><b>Evolutionsstrategien</b> (ES) und <b>CMA-ES</b>: reellwertige Vektoren, Mutation mit sich anpassenden Schrittweiten {r('BS02')} {r('Han16')}. Die Standardwahl für stetige Parameter.</li>
<li><b>Differentielle Evolution</b> (DE): mutiert, indem sie die Differenz zweier anderer Kandidaten addiert, kreuzt dann mit dem Elternteil und behält den besseren der beiden {r('SP97')}.</li>
<li><b>Genetische Programmierung</b> (GP): Kandidaten sind Programme — die Grundlage von GenProg und Genetic Improvement.</li>
<li><b>NSGA-II</b>: mehrere Ziele zugleich; liefert eine Pareto-Front von Kompromissen statt eines Besten {r('Deb02')}. In der modellgetriebenen Entwicklung optimiert PerOpteryx damit Architekturmodelle nach Leistung, Zuverlässigkeit und Kosten {r('PerOp')} — zu Modellen siehe <a href="research-mde.html">Teil 1</a>.</li>
<li><b>MAP-Elites</b> und Novelty Search: halten den besten Kandidaten für jede Art von Verhalten {r('MC15')} — die Programmdatenbank von AlphaEvolve ist davon inspiriert {r('AlphaE')}.</li>
<li><b>NEAT</b> und Neuroevolution: evolvieren neuronale Netze, samt Topologie {r('SM02')}.</li></ul>"""))
        + curious(lang, T(f"""<p>Evolution strategies also scale like few other methods. Because each candidate is scored independently and only scores need to be exchanged, Salimans and colleagues ran ES on 1,440 workers and taught a simulated humanoid to walk “in under 10 minutes” — a competitive alternative to reinforcement learning with gradients {r('Sal17')}. David Ha’s visual guide shows several of these strategies side by side on 2-D landscapes {r('Ha17')}.</p>""",
                          f"""<p>Evolutionsstrategien skalieren zudem wie wenige andere Verfahren. Weil jeder Kandidat unabhängig bewertet wird und nur Bewertungen ausgetauscht werden müssen, ließen Salimans und Kollegen ES auf 1.440 Rechnern laufen und brachten einem simulierten Humanoiden in unter 10 Minuten das Laufen bei — eine konkurrenzfähige Alternative zu Reinforcement Learning mit Gradienten {r('Sal17')}. David Has visuelle Anleitung zeigt mehrere dieser Strategien nebeneinander auf 2-D-Landschaften {r('Ha17')}.</p>"""),
                  T("Evolution at scale", "Evolution im großen Maßstab"))))
    S.append(("phev", 3, T("Case: energy management in a hybrid car", "Fall: Energiemanagement im Hybridauto"),
        L(T(f"""<p>A plug-in hybrid has two engines on one axle: a combustion engine and an electric motor. Every 0.02 seconds its controller decides how to split the requested torque between them — burn fuel now, or use the battery and recharge it later? In the DFG project OASys at RWTH’s Theory of Hybrid Systems group, we built a controller around a genetic algorithm {cite('NWN+15')}; geneial started as its framework.</p>""",
              f"""<p>Ein Plug-in-Hybrid hat zwei Motoren an einer Achse: einen Verbrennungsmotor und einen Elektromotor. Alle 0,02 Sekunden entscheidet seine Steuerung, wie sie das angeforderte Drehmoment aufteilt — jetzt Kraftstoff verbrennen oder die Batterie nutzen und später nachladen? Im DFG-Projekt OASys am Lehr- und Forschungsgebiet Theorie der hybriden Systeme der RWTH haben wir eine Steuerung um einen genetischen Algorithmus gebaut {cite('NWN+15')}; geneial entstand als ihr Framework.</p>"""))
        + demo_phev(lang)
        + L(T(f"""<p>The weights are the specification, as in chapter 01: telling the GA to care only about fuel gave a worse fuel result than adding “keep the battery near its target” — a plausible reading is that the battery term adds foresight beyond the 20-second window. With the best weighting, the GA used up to 1.8 % less fuel than the best of the published reference controllers it was compared with {cite('NWN+15')}. And smooth driving — the engine should not switch on and off every second — competes with fuel:</p>""",
              f"""<p>Die Gewichte sind die Spezifikation, wie in Kapitel 01: Dem GA zu sagen, er solle nur auf Kraftstoff achten, ergab ein schlechteres Kraftstoffergebnis, als „Batterie nahe am Ziel halten“ hinzuzunehmen — naheliegend ist, dass der Batterie-Term Voraussicht über das 20-Sekunden-Fenster hinaus einbringt. Mit der besten Gewichtung verbrauchte der GA bis zu 1,8 % weniger Kraftstoff als die beste der veröffentlichten Vergleichs-Steuerungen {cite('NWN+15')}. Und ruhiges Fahren — der Motor soll nicht jede Sekunde an- und ausgehen — konkurriert mit dem Kraftstoff:</p>"""))
        + fig_phev_tradeoff(lang)
        + curious(lang, T(f"""<p>Why a GA inside a control loop, where every step has a deadline? Because it is an anytime algorithm with a fixed budget: 50 candidates for 100 generations fit into the time step. Because its population carries over from step to step — shifted by one gene, it is already a good guess for the next decision. And because the fitness can be any mix of goals, including ones that are hard to put into a formula for a classical controller. A larger population starts and ends higher, but costs time; 50 was the compromise for real time {cite('NWN+15')}.</p>""",
                          f"""<p>Warum ein GA in einem Regelkreis, in dem jeder Schritt eine Frist hat? Weil er ein Anytime-Algorithmus mit festem Budget ist: 50 Kandidaten für 100 Generationen passen in den Zeitschritt. Weil seine Population von Schritt zu Schritt erhalten bleibt — um ein Gen verschoben ist sie schon eine gute Schätzung für die nächste Entscheidung. Und weil die Fitness jede Mischung von Zielen sein kann, auch solche, die sich für einen klassischen Regler schwer in eine Formel bringen lassen. Eine größere Population startet und endet höher, kostet aber Zeit; 50 war der Kompromiss für Echtzeit {cite('NWN+15')}.</p>"""),
                  T("Why a GA inside a controller?", "Warum ein GA in einer Steuerung?"))))
    S.append(("windfarm", 3, T("Case: offshore wind-farm layout", "Fall: Layout eines Offshore-Windparks"),
        L(T(f"""<p>The real version of our toy: Horns Rev 1 in the Danish North Sea, 80 Vestas V80 turbines on 3.8 × 5 km, wind data of eight years, rated by annual energy production, net present value and internal rate of return {cite('Net17')}. Genetic algorithms are a classic tool for placing wind turbines {r('Gra05')}; the question of my thesis was narrower: should the positions be free floating-point numbers or points on a grid? The thesis set the grid to a 0.1 m spacing — fine, but not finer than the model can use — and compared both encodings, each with the configuration recommended for it:</p>""",
              f"""<p>Die echte Fassung unseres Spielzeugs: Horns Rev 1 in der dänischen Nordsee, 80 Anlagen vom Typ Vestas V80 auf 3,8 × 5 km, Winddaten aus acht Jahren, bewertet nach Jahresenergieertrag, Kapitalwert und internem Zinsfuß {cite('Net17')}. Genetische Algorithmen sind ein klassisches Werkzeug, um Windkraftanlagen zu platzieren {r('Gra05')}; die Frage meiner Arbeit war enger: Sollen die Positionen freie Gleitkommazahlen oder Punkte auf einem Raster sein? Die Arbeit legte das Raster auf 0,1 m Abstand — fein, aber nicht feiner, als das Modell nutzen kann — und verglich beide Codierungen, jede mit der für sie empfohlenen Konfiguration:</p>"""))
        + fig_runtimes(lang)
        + L(T(f"""<p>The thesis concludes that discretised genes are “much more efficient and yield better results in all test cases” {cite('Net17')}. Read with the caveat in the caption, the lesson that carries over to your own problem is the one from the encoding section: match the resolution of the genes to the resolution of the score, and do not pay for precision nobody can see.</p>""",
              f"""<p>Die Arbeit folgert, dass diskretisierte Gene viel effizienter sind und in allen Testfällen bessere Ergebnisse liefern {cite('Net17')}. Mit dem Vorbehalt aus der Bildunterschrift gelesen, ist die Lehre, die sich auf Ihr eigenes Problem überträgt, die aus dem Abschnitt zur Codierung: Passen Sie die Auflösung der Gene an die Auflösung der Bewertung an, und bezahlen Sie nicht für Genauigkeit, die niemand sieht.</p>"""))))
    hi = _seeds(S_HIGH, lang)
    lo = _seeds(S_LOW, lang)
    S.append(("tryit", 3, T("Try it yourself", "Selbst ausprobieren"),
        L(T(f"""<p>The whole algorithm of the convergence figure, in plain Python without any library — the “balanced” setting on the two hills. Copy it, run it, then change one knob at a time:</p>""",
              f"""<p>Der ganze Algorithmus aus der Konvergenz-Abbildung, in einfachem Python ohne Bibliothek — die Einstellung „ausgewogen“ auf den zwei Hügeln. Kopieren, ausführen, dann einen Regler nach dem anderen ändern:</p>"""))
        + f'<pre class="mono art-pre">{sim.STARTER.replace("<", "&lt;")}</pre>'
        + L(T(f"""<div class="tryit"><span class="k mono">WHAT YOU WILL SEE</span><p>Seeds {lo} end on the low hill with fitness 0.600; seeds {hi} reach the high one (≥ 0.99). Every run costs {S_EVALS:,} evaluations. Three out of ten on the wrong hill — that is why you run seeds. Try <code>newcomers=0</code>, <code>k=8</code> or <code>p_mut=0</code> and count again.</p></div>""",
              f"""<div class="tryit"><span class="k mono">WAS SIE SEHEN WERDEN</span><p>Die Seeds {lo} enden auf dem niedrigen Hügel mit Fitness 0,600; die Seeds {hi} erreichen den hohen (≥ 0,99). Jeder Lauf kostet {S_EVALS:,} Bewertungen. Drei von zehn auf dem falschen Hügel — deshalb lässt man mehrere Seeds laufen. Probieren Sie <code>newcomers=0</code>, <code>k=8</code> oder <code>p_mut=0</code> und zählen Sie erneut.</p></div>""".replace("1,100", "1.100")))
        + L(T(f"""<p>For real problems, use a library. They differ in what they make easy:</p>""",
              f"""<p>Für echte Probleme nehmen Sie eine Bibliothek. Sie unterscheiden sich darin, was sie leicht machen:</p>"""))
        + frameworks(lang)
        + L(T(f"""<p>The ask–tell loop of chapter 02, literally, with CMA-ES for two real numbers (adapted from the <code>cmaes</code> README):</p>""",
              f"""<p>Die Erfragen-Mitteilen-Schleife aus Kapitel 02, wörtlich, mit CMA-ES für zwei reelle Zahlen (nach dem README von <code>cmaes</code>):</p>"""))
        + f'<pre class="mono art-pre">{CMAES}</pre>'
        + L(T(f"""<p>To watch evolution without writing code, try <a href="https://rednuht.org/genetic_cars_2/" target="_blank" rel="noopener">Genetic Cars 2 ↗</a>, where a GA breeds two-wheeled cars and lets you change the mutation rate and the elite while they drive. The library behind the figures of my thesis, <a href="projects-geneial.html">geneial</a>, is open source (C++11, MIT) {r('geneial')} but no longer maintained. And if your system already has a <a href="research-dt.html">digital twin</a>, an optimiser like these can become one of its services.</p>""",
              f"""<p>Um Evolution ohne Code zuzusehen, probieren Sie <a href="https://rednuht.org/genetic_cars_2/" target="_blank" rel="noopener">Genetic Cars 2 ↗</a>, wo ein GA zweirädrige Autos züchtet und Sie Mutationsrate und Elite ändern können, während sie fahren. Die Bibliothek hinter den Abbildungen meiner Arbeit, <a href="projects-geneial.html">geneial</a>, ist Open Source (C++11, MIT) {r('geneial')}, wird aber nicht mehr gepflegt. Und wenn Ihr System schon einen <a href="research-dt.html">digitalen Zwilling</a> hat, kann ein Optimierer wie diese einer seiner Services werden.</p>"""))))
    S.append(("summary", 1, T("In short", "Kurz gesagt"),
        L(T(f"""<ul class="pts"><li><b>One loop with exchangeable parts:</b> propose candidates, score them, keep the better ones, repeat. You write the encoding and the score; libraries supply the rest.</li>
<li><b>No gradient, no training data — only a score.</b> The price is evaluations: population × generations, each possibly a slow simulation.</li>
<li><b>The encoding is the main design decision.</b> It decides which operators make sense and how big the space is; resolve no finer than the score can tell apart.</li>
<li><b>The score is the specification.</b> Evolution optimises exactly what you measure — patches that delete features, a fuel-only controller that uses more fuel.</li>
<li><b>Selection pressure works against diversity.</b> Every knob moves the balance between exploring and exploiting; a run that loses its diversity has converged, right or wrong.</li>
<li><b>Randomness is a tool, so measure it:</b> run several seeds, log best, mean and diversity, and compare with random search.</li></ul>""",
              f"""<ul class="pts"><li><b>Eine Schleife mit austauschbaren Teilen:</b> Kandidaten vorschlagen, bewerten, die Besseren behalten, wiederholen. Sie schreiben Codierung und Bewertung; den Rest liefern Bibliotheken.</li>
<li><b>Kein Gradient, keine Trainingsdaten — nur eine Bewertung.</b> Der Preis sind Bewertungen: Population × Generationen, jede womöglich eine langsame Simulation.</li>
<li><b>Die Codierung ist die wichtigste Entwurfsentscheidung.</b> Sie entscheidet, welche Operatoren sinnvoll sind und wie groß der Raum ist; lösen Sie nicht feiner auf, als die Bewertung unterscheiden kann.</li>
<li><b>Die Bewertung ist die Spezifikation.</b> Evolution optimiert genau das, was Sie messen — Patches, die Funktionen löschen, eine Nur-Kraftstoff-Steuerung, die mehr verbraucht.</li>
<li><b>Selektionsdruck arbeitet gegen Vielfalt.</b> Jeder Regler verschiebt das Gleichgewicht zwischen Erkunden und Ausnutzen; ein Lauf, der seine Vielfalt verliert, ist konvergiert, richtig oder falsch.</li>
<li><b>Zufall ist ein Werkzeug, also messen Sie ihn:</b> mehrere Seeds laufen lassen, Bestes, Mittel und Vielfalt mitschreiben und mit Zufallssuche vergleichen.</li></ul>"""))
        + L(T(f"""<div class="fit"><div><span class="k mono">WORTH IT WHEN</span><ul class="pts"><li>you can score a candidate, but there is no gradient</li><li>the space is huge, discrete or mixed, with many local optima</li><li>several objectives pull against each other</li><li>hundreds to thousands of evaluations are affordable, and “very good” is good enough</li></ul></div>
<div><span class="k mono">SOMETHING ELSE IS ENOUGH WHEN</span><ul class="pts"><li>gradients exist, or the problem is convex</li><li>an exact solver fits the problem — SAT, SMT, integer programming (see <a href="projects-smt-rat.html">SMT-RAT</a>)</li><li>only a few dozen evaluations are affordable</li><li>you need a guarantee of optimality</li></ul></div></div>""",
              f"""<div class="fit"><div><span class="k mono">LOHNT SICH, WENN</span><ul class="pts"><li>Sie einen Kandidaten bewerten können, es aber keinen Gradienten gibt</li><li>der Raum riesig, diskret oder gemischt ist, mit vielen lokalen Optima</li><li>mehrere Ziele gegeneinander ziehen</li><li>Hunderte bis Tausende Bewertungen bezahlbar sind und „sehr gut“ gut genug ist</li></ul></div>
<div><span class="k mono">ETWAS ANDERES REICHT, WENN</span><ul class="pts"><li>es Gradienten gibt oder das Problem konvex ist</li><li>ein exakter Solver passt — SAT, SMT, ganzzahlige Optimierung (siehe <a href="projects-smt-rat.html">SMT-RAT</a>)</li><li>nur ein paar Dutzend Bewertungen bezahlbar sind</li><li>Sie eine Garantie für Optimalität brauchen</li></ul></div></div>"""))))
    out, n = [], 0
    for sid, level, head, html_ in S:
        name = L(head) if isinstance(head, dict) else head
        if level == 2:
            n += 1
            out.append(f'      <section class="art-sec art-ch"><h2 id="{sid}"><span class="mono">0{n}</span>{name}</h2>{html_}</section>')
        elif level == 1:
            out.append(f'      <section class="art-sec art-ch"><h2 id="{sid}">{name}</h2>{html_}</section>')
        else:
            h = f'<h3 id="{sid}">{name}</h3>' if head else ""
            out.append(f'      <section class="art-sec">{h}{html_}</section>')
    toc = "".join(f'<a href="#{sid}">{L(head)}</a>' for sid, level, head, _ in S if level == 2)
    refs = "".join(f'<li id="ref-{k}">{t}</li>' for k, (_, t) in enumerate(REFS, 1))
    return toc, NL.join(out), refs


def page(lang):
    """Returns (file, title, description, body, scripts) for build.py."""
    L = lambda x: x[lang]
    A = "../" if lang == "de" else ""
    toc, sections, refs = body(lang, A)
    html_ = f'''
    <header class="page proj">
      <a class="back mono" href="research.html">← {L(T("research", "Forschung"))}</a>
      <div class="section-head">
        <h1><span class="mono">02</span>{L(T("Evolutionary Algorithms", "Evolutionäre Algorithmen"))}</h1>
        <span class="mono faint">{L(T("article · 2026", "Artikel · 2026"))}</span>
      </div>
      <p class="lead">{L(T("Evolution as an algorithm: many guesses, a score, and a few rules for which guesses get to have children — what <em>evolutionary algorithms</em> are, how each step works, and when to use them.",
                          "Evolution als Algorithmus: viele Versuche, eine Bewertung und ein paar Regeln, welche Versuche Kinder bekommen — was <em>evolutionäre Algorithmen</em> sind, wie jeder Schritt funktioniert und wann man sie einsetzt."))}</p>
      {series(lang, FILE)}
      <nav class="chapters mono" aria-label="{L(T("Chapters", "Kapitel"))}">{toc}</nav>
    </header>
    {hero_ea(lang)}
    <article class="article">
{sections}
      <section class="art-sec art-refs">
        <h2 id="literature">{L(T("Literature", "Literatur"))}</h2>
        <ol class="refs mono">{refs}</ol>
        <div class="group mono">{L(T("My papers on the topic", "Eigene Arbeiten zum Thema"))}</div>
        <ol class="pubs">
{pub_list(lang, OWN)}
        </ol>
      </section>
    </article>
'''
    desc = T("Evolutionary and genetic algorithms explained with interactive figures: where they sit next to machine learning, how selection, crossover and mutation work, and how to try them — an article by Lukas Netz.",
             "Evolutionäre und genetische Algorithmen, erklärt mit interaktiven Abbildungen: wo sie neben maschinellem Lernen stehen, wie Selektion, Crossover und Mutation funktionieren und wie man sie ausprobiert — ein Artikel von Lukas Netz.")
    return FILE, T("Evolutionary Algorithms", "Evolutionäre Algorithmen"), desc, html_, f'<link rel="stylesheet" href="{A}assets/ea.css">\n<script src="{A}assets/ea.js"></script>\n'
